    <style>
        :root{color-scheme:light;--blue:#173f91;--ink:#172033;--muted:#64748b;--line:#dbe3ef;--bg:#f4f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,Helvetica,sans-serif}.wrap{width:min(760px,100%);margin:auto;padding:16px}.top{display:flex;align-items:center;gap:12px;padding:14px 16px;border-radius:18px;background:var(--blue);color:#fff;box-shadow:0 12px 28px #173f9126}.logo{width:42px;height:42px;border-radius:12px;background:#fff;padding:6px;object-fit:contain}.top small{display:block;margin-top:3px;color:#c9d8ff}.card{margin-top:14px;border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 8px 24px #0f172a0b;overflow:hidden}.equipment{display:grid;gap:16px;padding:16px}.photo{width:100%;aspect-ratio:16/10;border-radius:14px;background:#eef2f7;object-fit:cover}.placeholder{display:grid;place-items:center;color:var(--muted);font-weight:700}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.12em;color:var(--blue);text-transform:uppercase}.title{margin:6px 0 0;font-size:23px;line-height:1.15}.code{display:inline-block;margin-top:10px;padding:6px 10px;border-radius:999px;background:#eaf1ff;color:#123b8d;font-size:13px;font-weight:800}.meta{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.meta div{padding:10px;border-radius:12px;background:#f8fafc}.meta span{display:block;font-size:10px;font-weight:800;letter-spacing:.08em;color:var(--muted);text-transform:uppercase}.meta strong{display:block;margin-top:4px;font-size:13px}.section-head{padding:15px 16px;border-bottom:1px solid var(--line)}.section-title-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-head h2{margin:0;font-size:16px}.section-head p{margin:5px 0 0;color:var(--muted);font-size:12px}.pdf-link{display:inline-flex;width:34px;height:34px;flex:none;align-items:center;justify-content:center;border:1px solid #fecaca;border-radius:10px;background:#fff5f5;color:#b91c1c;text-decoration:none}.pdf-link:hover{background:#fee2e2}.pdf-link svg{width:17px;height:17px}.body{padding:16px}.counts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.count{padding:10px 6px;border-radius:12px;text-align:center;font-size:11px;font-weight:700}.count strong{display:block;font-size:20px}.a{background:#e9f9ef;color:#166534}.b{background:#fff7db;color:#92400e}.c{background:#feecec;color:#991b1b}.summary{margin:12px 0 0;padding:12px;border-radius:12px;background:#f8fafc;font-size:13px;line-height:1.5}.checklist{margin-top:12px;border:1px solid var(--line);border-radius:13px;overflow:hidden}.item{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:11px 12px;border-top:1px solid var(--line);font-size:13px}.item:first-child{border-top:0}.item-copy{min-width:0}.remark{display:block;margin-top:4px;color:var(--muted);font-size:11px;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere}.remark strong{color:#475569}.rating{min-width:32px;border-radius:9px;padding:5px;text-align:center;font-weight:900}.history{padding:0 14px 14px}.entry{margin-top:12px;border:1px solid var(--line);border-radius:14px;overflow:hidden}.entry summary{cursor:pointer;list-style:none;padding:13px}.entry summary::-webkit-details-marker{display:none}.row{display:flex;align-items:center;justify-content:space-between;gap:10px}.entry-actions{display:flex;align-items:center;gap:7px}.date{font-size:14px;font-weight:800}.doc{margin-top:4px;color:var(--muted);font-size:11px;word-break:break-word}.approved{border-radius:999px;background:#e9f9ef;color:#166534;padding:5px 8px;font-size:10px;font-weight:800}.details{border-top:1px solid var(--line);padding:12px}.empty{padding:32px 18px;text-align:center;color:var(--muted);font-size:14px}.notice{margin:14px 0 4px;padding:13px;border-radius:14px;border:1px solid #f0cf7a;background:#fffbeb;color:#744210;font-size:12px;line-height:1.5}.pagination{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:14px;color:var(--muted);font-size:12px}.page-link{border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--blue);padding:8px 11px;font-weight:700;text-decoration:none}.page-link.disabled{color:#94a3b8;pointer-events:none}@media(min-width:620px){.wrap{padding:24px}.equipment{grid-template-columns:220px 1fr;align-items:center}.photo{aspect-ratio:4/3}}
